package org.simpleweather.app;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Hierarchical, local preferences; dialogs do not reset their parent settings page. */
final class SettingsScreen {
    private final MainActivity a;
    private final SharedPreferences prefs;
    SettingsScreen(MainActivity a){this.a=a;prefs=a.preferences;}
    private LinearLayout form(){LinearLayout c=a.column();c.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(16));return c;}
    private AlertDialog dialog(String title,LinearLayout c){ScrollView scroll=new ScrollView(a);scroll.addView(c);return new ToolDialog(a).setTitle(title).setView(scroll).setPositiveButton("完成",null).show();}
    private void action(LinearLayout c,String label,Runnable click){c.addView(a.button(label,false,click));a.gap(c,10);}
    void show(){String[] names={"背景","描边","天气","课程表","定位","天气地图","底部栏目","关于"};new ToolDialog(a).setTitle("设置").setItems(names,(d,n)->{switch(n){case 0:background();break;case 1:outline();break;case 2:weather();break;case 3:a.scheduleSettings();break;case 4:location();break;case 5:maps();break;case 6:order(false);break;case 7:about();}}).setNegativeButton("关闭",null).show();}
    private void background(){LinearLayout c=form();action(c,"从手机导入并调整背景",a::selectBackground);action(c,"恢复默认背景",a::resetBackground);c.addView(a.text("背景遮罩 · 调整文字清晰度",14,a.INK,true));SeekBar shade=new SeekBar(a);shade.setMax(90);shade.setProgress(prefs.getInt("shade",80)-10);shade.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean user){if(user)prefs.edit().putInt("shade",n+10).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){a.refreshScreen();}});c.addView(shade,a.lp(-1,48));dialog("背景",c);}
    private void outline(){LinearLayout c=form();Switch toggle=new Switch(a);toggle.setText("显示区域与按钮描边");toggle.setTextSize(15);toggle.setChecked(prefs.getBoolean("outline",true));toggle.setOnCheckedChangeListener((v,on)->{prefs.edit().putBoolean("outline",on).apply();a.refreshScreen();});c.addView(toggle,a.lp(-1,54));a.gap(c,10);action(c,"描边颜色（默认黑色）",()->{String[] labels={"黑色","深灰","蓝色","绿色","红色","紫色","白色","自定义十六进制颜色"};int[] colors={Color.BLACK,0xFF555555,0xFF246BCE,0xFF287C60,0xFFB83636,0xFF7852A8,Color.WHITE};new ToolDialog(a).setTitle("描边颜色").setItems(labels,(d,n)->{if(n<colors.length){prefs.edit().putInt("outline_color",colors[n]).apply();a.refreshScreen();}else customColor();}).show();});c.addView(a.text("支持预设颜色及 #RRGGBB 自定义颜色。",13,a.MUTED,false));dialog("描边",c);}
    private void customColor(){EditText input=new EditText(a);input.setSingleLine(true);input.setHint("#000000");input.setText(String.format(Locale.ROOT,"#%06X",a.outlineColor()&0xffffff));input.setSelectAllOnFocus(true);AlertDialog d=new ToolDialog(a).setTitle("输入 #RRGGBB 颜色").setView(input).setPositiveButton("保存",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{String s=input.getText().toString().trim();if(!s.matches("#[0-9a-fA-F]{6}")){a.toast("请输入 # 加六位十六进制颜色");return;}prefs.edit().putInt("outline_color",Color.parseColor(s)).apply();a.refreshScreen();d.dismiss();}));d.show();}
    void weather(){LinearLayout c=form();action(c,"栏目显示与排序",()->order(true));action(c,"查看图例",this::legend);dialog("天气设置",c);}
    private void legend(){LinearLayout c=form();int[] codes={0,1,2,3,45,48,51,53,55,56,57,61,63,65,66,67,71,73,75,77,80,81,82,85,86,95,96,99,-1};c.addView(a.text("左为白天，右为夜间；图标对应 WMO 天气代码。",13,a.MUTED,false));for(int code:codes){LinearLayout r=a.row();r.addView(new WeatherIcon(a,code,true),a.lp(46,46));r.addView(new WeatherIcon(a,code,false),a.lp(46,46));r.addView(a.text(WeatherData.condition(code)+(code>=0?" · "+code:""),14,a.INK,false),new LinearLayout.LayoutParams(0,-2,1));c.addView(r);a.gap(c,6);}dialog("天气图例",c);}
    void location(){String[] names={"GPS 硬件定位","网络定位（系统提供）"};int current=prefs.getString("location_provider","gps").equals("network")?1:0;new ToolDialog(a).setTitle("定位方式").setSingleChoiceItems(names,current,(d,n)->{prefs.edit().putString("location_provider",n==0?"gps":"network").apply();a.locationModeChanged();d.dismiss();}).setNegativeButton("返回",null).show();}
    void maps(){String[] names={"全国","华北","东北","华东","华中","华南","西南","西北","中国天气网"};int selected=Math.max(0,Math.min(8,prefs.getInt("radar_region",0)));new ToolDialog(a).setTitle("天气地图 · 默认雷达").setSingleChoiceItems(names,selected,(d,n)->{prefs.edit().putInt("radar_region",n).apply();a.refreshScreen();d.dismiss();}).setNegativeButton("返回",null).show();}
    private void about(){LinearLayout c=form();action(c,"版本更新记录",a::updates);action(c,"数据来源与隐私",a::about);c.addView(a.text("呆呆工具箱 1.0.1",14,a.MUTED,false));dialog("关于",c);}
    private void order(boolean weather){
        String[] labels=weather?MainActivity.WEATHER_NAMES:MainActivity.TAB_NAMES;String key=weather?"weather":"tab";List<Integer> ids=DisplayOrder.parse(prefs.getString(key+"_order",""),labels.length);LinearLayout c=form();c.addView(a.text(weather?"勾选显示，使用箭头调整上下顺序。来源署名跟随天气内容保留。":"至少保留一个栏目；一个栏目时隐藏底栏，五个栏目时使用左右箭头翻页。",13,a.MUTED,false));a.gap(c,12);LinearLayout list=a.column();c.addView(list);Runnable[] render=new Runnable[1];render[0]=()->{list.removeAllViews();for(int pos=0;pos<ids.size();pos++){final int index=pos,id=ids.get(pos);LinearLayout r=a.row();CheckBox check=new CheckBox(a);check.setText(labels[id]);check.setTextSize(14);check.setChecked(prefs.getBoolean(key+"_show_"+id,weather||id<3));check.setOnCheckedChangeListener((v,on)->{if(!weather&&!on&&a.visibleTabs().size()<=1){check.setChecked(true);a.toast("至少保留一个底部栏目");return;}prefs.edit().putBoolean(key+"_show_"+id,on).apply();a.refreshScreen();});r.addView(check,new LinearLayout.LayoutParams(0,-2,1));TextView up=a.button("↑",false,()->{if(index>0){Collections.swap(ids,index,index-1);prefs.edit().putString(key+"_order",DisplayOrder.encode(ids)).apply();a.refreshScreen();render[0].run();}});up.setContentDescription(labels[id]+"上移");up.setPadding(0,0,0,0);r.addView(up,a.lp(42,48));TextView down=a.button("↓",false,()->{if(index+1<ids.size()){Collections.swap(ids,index,index+1);prefs.edit().putString(key+"_order",DisplayOrder.encode(ids)).apply();a.refreshScreen();render[0].run();}});down.setContentDescription(labels[id]+"下移");down.setPadding(0,0,0,0);r.addView(down,a.lp(42,48));list.addView(r);a.gap(list,8);}};render[0].run();dialog(weather?"天气栏目显示与排序":"底部栏目显示与排序",c);
    }
}
